




"use strict";




const PLUGIN_NAME = "PlatformPlugin";





class PlatformPlugin {
	



	constructor(platform) {
		
		this.platform = platform;
	}

	




	apply(compiler) {
		compiler.hooks.environment.tap(PLUGIN_NAME, () => {
			compiler.platform = {
				...compiler.platform,
				...this.platform
			};
		});
	}
}

module.exports = PlatformPlugin;
